    STORE_PTR(GamePtrs.frame_rate_draw); // OFF_FRAMERATE
    STORE_PTR(GamePtrs.PingTime); // OFF_PING
    STORE_PTR(GamePtrs.GameTurn); // OFF_GAME_TIME
