    STORE_PTR(GamePtrs.BuildingsAvailable);// OFF_BUILDING_PANEL
    STORE_PTR(GamePtrs.PlayerFlags); // OFF_GOD
    STORE_PTR(GamePtrs.spells_type_info); // OFF_SPELLS
