    STORE_PTR(GamePtrs.NumBuildingsOfType); // OFF_PLAYER_BUILDINGS
    STORE_PTR(GamePtrs.SpellsCast); // OFF_PLAYER_SPELLS
	
                                                             // OFF_RESYNC_ON
                                                             // OFF_RESYNC_COUNT
                                                             // OFF_CHEAT_FLAGS
                                                             // OFF_CHEAT_BYRNE
                                                             // OFF_OBJECT_LIST
                                                             // OFF_SHAMAN_LIMIT
