#if !POP3_BUILD_USE_SDL2
// Clip the OS cursor to this window's client rect (in screen coords) while
// the window is focused. Released when focus is lost so the user can reach
// other windows, the taskbar, etc. Called from WM_SETFOCUS / WA_ACTIVE /
// WM_SIZE / WM_MOVE below. No-op in fullscreen (the clip would cover the
// whole monitor anyway) and on minimised windows (zero-size client rect).
static void clipCursorToClientRect(HWND hWnd)
{
    if (!hWnd || IsIconic(hWnd)) return;
    RECT rc;
    if (!GetClientRect(hWnd, &rc)) return;
    POINT tl = { rc.left, rc.top };
    POINT br = { rc.right, rc.bottom };
    if (!ClientToScreen(hWnd, &tl)) return;
    if (!ClientToScreen(hWnd, &br)) return;
    if (br.x <= tl.x || br.y <= tl.y) return;
    RECT screenRc = { tl.x, tl.y, br.x, br.y };
    ClipCursor(&screenRc);
}

static void releaseCursorClip()
{
    ClipCursor(nullptr);
}

// True while the user is dragging the title bar or resizing the window
// (between WM_ENTERSIZEMOVE and WM_EXITSIZEMOVE). During this interval
// we must NOT re-clip the cursor — doing so fights the window drag and
// makes the window jump or stick.
static bool _inSizeMove = false;

Pop3Result POP3_CALLBACK Pop3App::MainWindowProc(Pop3WindowHandle hwnd, UINT msg, Pop3WParam wParam, Pop3LParam lParam)
{
    HWND hWnd = (HWND)hwnd;
    if (_quitting) return DefWindowProc(hWnd, msg, (WPARAM)wParam, (LPARAM)lParam);

    switch (msg)
    {
    case WM_MOUSEMOVE:
    case WM_INPUT:
        return Pop3Input::ProcessEvent(hwnd, msg, wParam, lParam);
    case WM_MOUSEACTIVATE:
    case WM_SYSKEYUP:
    case WM_KEYUP:
    case WM_KEYDOWN:
    case WM_SYSKEYDOWN:
        return 0;
    case WM_CHAR:
        return Pop3Input::ProcessEvent(hwnd, msg, wParam, lParam);;
    case WM_QUIT:
    case WM_ENDSESSION:
    case WM_CLOSE:
    case WM_DESTROY:
        // Causes issues with D3D which
        // _EventCallback is used for.
        _quitting = true;
        releaseCursorClip();
        return 0;
        break;
    case WM_CHILDACTIVATE:
    case WM_GETMINMAXINFO:
        Pop3Input::resetKeys();
        break;
    case WM_SETFOCUS:
        _active = true;
        Pop3Input::resetKeys();
        clipCursorToClientRect(hWnd);
        break;
    case WM_KILLFOCUS:
        _active = false;
        Pop3Input::resetKeys();
        releaseCursorClip();
        break;
    case WM_SIZE:
        switch (wParam)
        {
        case SIZE_MAXHIDE:
        case SIZE_RESTORED:
        case SIZE_MAXIMIZED:
        case SIZE_MAXSHOW:
            _active = true;
            break;
        case SIZE_MINIMIZED:
            _active = false;
            break;
        default:;
        }
        Pop3Input::resetKeys();
        // Client rect may have moved in screen coords — re-clip, but NOT
        // while the user is dragging/resizing (WM_SIZE fires continuously
        // during a resize drag; re-clipping would fight the resize).
        if (!_inSizeMove)
        {
            if (_active)
                clipCursorToClientRect(hWnd);
            else
                releaseCursorClip();
        }
        break;
    case WM_MOVE:
        // Window moved — re-clip unless the user is actively dragging the
        // title bar. WM_MOVE fires for every pixel of a drag; re-clipping
        // would snap the cursor back and make the window unmovable.
        if (_active && !_inSizeMove)
            clipCursorToClientRect(hWnd);
        break;
    case WM_ACTIVATE:
        switch (LOWORD((WPARAM)wParam))
        {
        case WA_ACTIVE:
            _active = true;
            clipCursorToClientRect(hWnd);
            break;
        case WA_CLICKACTIVE:
        {
            _active = true;
            // Only clip if the click landed inside the client area. A
            // title-bar / border click will start a drag/resize — clipping
            // now would snap the cursor off the title bar and make the
            // window jump to the bottom of the screen.
            POINT pt;
            GetCursorPos(&pt);
            ScreenToClient(hWnd, &pt);
            RECT rc;
            GetClientRect(hWnd, &rc);
            if (PtInRect(&rc, pt))
                clipCursorToClientRect(hWnd);
            break;
        }
        case WA_INACTIVE:
            _active = false;
            releaseCursorClip();
            break;
        default:;
        }
        Pop3Input::resetKeys();
        break;
    case WM_ENTERSIZEMOVE:
        // User grabbed the title bar or a resize edge — release so they can
        // drag freely. We'll re-clip on WM_EXITSIZEMOVE.
        _inSizeMove = true;
        releaseCursorClip();
        break;
    case WM_EXITSIZEMOVE:
        _inSizeMove = false;
        if (_active)
            clipCursorToClientRect(hWnd);
        break;
    case WM_SETCURSOR:
        SetCursor(nullptr);
		return TRUE;
	case WM_SYSCOMMAND:
	if (wParam == SC_CLOSE)
	{
		_quitting = true;
		return 0;
	}
    default:;
    }
    if (_EventCallback)
        return _EventCallback(hwnd, msg, wParam, lParam);
    return DefWindowProc(hWnd, msg, (WPARAM)wParam, (LPARAM)lParam);
}
#endif
#endif

