        Self {
            //objs0_dat: mk_based_path(base, format!("objs0-{key}.dat")),
            objs0_dat: mk_based_path(base, format!("OBJS0-{key}.DAT")),
            objs0_ver: mk_based_path(base, format!("objs0-{key}.ver")),
            pnts0: mk_based_path(base, format!("PNTS0-{key}.DAT")),
