                subs.single_player.tick_update_single_player();

                // 7b. AI_UpdateAllTribes (0x0041a7d0) — skip if victory/defeat
                // Original: TEST dword ptr [0x00884bf9], 0x800000; JNZ skip
                if !self.flags.is_victory_defeat() {
