        ($a:expr, $b:expr, $c:expr, $d:expr, $e:expr, $f:expr, $g:expr, $h:expr, $i:expr, $j:expr, $k:expr) => {
            TickSubsystems {
                terrain: $a, objects: $b, water: $c,
                network: $d, actions: $e, game_time: $f,
                single_player: $g, tutorial: $h, ai: $i,
                population: $j, mana: $k,
            }
        };
