enum { CC_ADD, CC_SUB, CC_LOGIC, CC_INC, CC_DEC, CC_SHL, CC_SHR, CC_SAR, CC_ADC, CC_SBB, CC_NEG, CC_MUL, CC_EFL };
#define CCOP(k, sz) ((k) * 4 + ((sz) == 1 ? 0 : (sz) == 2 ? 1 : 2))

