#define ST(i) R->st[(R->ftop + (i)) & 7]
// x87 precision control (FCW bits 8-9): 24 bits rounds to float; 53/64 bits use double
#define FPR(x) (__builtin_expect((R->fcw & 0x300) == 0, 0) ? (double)(float)(x) : (double)(x))
