bool		CPopulous::Init(	HINSTANCE	_hInstance,
					LPTSTR		_lpCmdLine,
					int			_nCmdShow)
{
	FILE	*FH;

	// Start by assuming we're gonna fail - does that say something about the way I look at things?
	GameState = GameError;

