/*
    Populous The Beginning Sprite Patcher
    Brandan Tyler Lasley 2019 (7/25/2019)
*/
#include "Sprite.h"
#include <iostream>

int main(int argc, char *argv[])
{
    if (argc > 2)
    {
        std::cout << argv[1] << " <---- " << argv[2];
    }
    else
    {
        std::cout << "Usage: <destnation> <source> \n";
        return -1;
    }

    std::string dest = argv[1];
    std::string source = argv[2];

    auto spr = Sprite(source);

    // Patch Image
    int8_t          byte, *curr;
    unsigned char   clr, rclr;
    int             num, j, y, x;

    auto hot_patch_spr_image = [&byte, &clr, &rclr, &curr, &num, &j, &y, &x](TbSprite & spr)
    {
        // Most of this code is just to scan the sprites X, Y locations and checking the byte
        // if its the color we want to replace. If it is we replace it in the j = 1 loop below.

        // This is also how you can draw sprites.
        curr = spr.data;
        y = 0;
        x = 0;
        while (y < spr.header->height)
        {
            byte = (*curr);
            curr++;
            if (byte == 0)
            {
                x = 0;
                y++;
            }
            else if (byte >= 127)
            {
                x = x + (256 - byte);
            }
            else
            {
                num = byte;
                for (j = 1; j <= num; j++)
                {
                    byte = *curr;
                    clr = *curr;
                    rclr = 0;

                    // BLUE
                    if (clr >= 216 && clr <= 223) // Blues pal color codes
                    {
                        rclr = clr - 76;
                        (*curr) = rclr; // Change pal color to this new pal color.
                    }

                    // RED
                    if (clr >= 240 && clr <= 247) // Reds pal color codes
                    {
                        rclr = clr - 32;
                        (*curr) = rclr; // Change pal color to this new pal color.
                    }

                    // YELLOW
                    if (clr >= 232 && clr <= 239) // Yellows pal color codes
                    {
                        rclr = clr - 72;
                        (*curr) = rclr; // Change pal color to this new pal color.
                    }

                    // GREEN 
                    if (clr >= 224 && clr <= 231) // Greens pal color codes
                    {
                        rclr = clr - 92;
                        (*curr) = rclr; // Change pal color to this new pal color.
                    }

                    curr++;
                    x++;
                }
            }
        }
        return true;
    };

    spr.processSprites(hot_patch_spr_image);
    spr.savespr(dest);

    return 0;
}

/*
    Populous The Beginning Sprite Patcher
    Brandan Tyler Lasley 2019 (7/25/2019)
*/
#pragma once
#include <vector>
#include <cstdint>
#include <string>
#include <fstream>
#include <memory>

#define SPRITE_MAGIC_SIZE 4

struct sprite_header
{
    int8_t      magic[SPRITE_MAGIC_SIZE];
    uint32_t    frame_count;
};

struct sprite_frame_header
{
    uint16_t width;
    uint16_t height;
    uint32_t offset;
};

struct TbSprite
{
    struct sprite_frame_header* header;
    int8_t*                     data;
};

struct SpriteFile
{
    sprite_header*						header;
    std::vector<TbSprite>               sprite_data;
};

class Sprite
{
public:
    Sprite() noexcept : _raw_file(nullptr), _raw_file_size(NULL), _data({ nullptr,{} }) {}

    Sprite(const std::string & file) : _raw_file(nullptr), _raw_file_size(NULL), _data({ nullptr, {} })
    {
        loadspr(file);
    }

    ~Sprite()
    {
        clean(_data);
    }

    void loadspr(const std::string & file)
    {
        std::ifstream reader(file, std::ios::binary | std::ios::ate);

        if (reader.is_open())
        {
            // Load file in full
            uint32_t byteLoc = 0;
            _raw_file_size = reader.tellg();
            reader.seekg(std::ios::beg);
            _raw_file = new char[static_cast<size_t>(_raw_file_size)];
            reader.read(_raw_file, _raw_file_size);
            reader.close();

            // Pointer Setup //

            // Header Pointer Setup
            _data.header = reinterpret_cast<sprite_header*>(_raw_file);

            // Increase byte location to add the size of sprite header.
            // This is so that we can ignore the sprite header when adding
            // the frame headers. 
            byteLoc += sizeof(sprite_header);

            // Frame Headers 
            for (uint32_t i = 0; i < _data.header->frame_count; i++)
            {
                _data.sprite_data.push_back({ reinterpret_cast<sprite_frame_header*>((_raw_file + byteLoc) + (i * sizeof(sprite_frame_header))), nullptr });
                _data.sprite_data.back().data = reinterpret_cast<int8_t*>(_raw_file + _data.sprite_data.back().header->offset);
            }

            reader.close();
        }
    }

    void savespr(const std::string & file)
    {
        std::ofstream writer(file, std::ios::binary | std::ios::trunc);

        if (writer.is_open())
        {
            writer.write(_raw_file, _raw_file_size);
            writer.close();
        }
    }

    void reset()
    {
        clean(_data);
    }

    template<typename lambda>
    TbSprite* processSprites(lambda func)
    {
        for (auto & spr_ptr : _data.sprite_data)
        {
            if (!func(spr_ptr))
                return &spr_ptr;
        }
        return nullptr;
    }
private:
    void clean(SpriteFile & sf)
    {
        sf.header = nullptr;
        sf.sprite_data.clear();
        delete[] _raw_file;
        _raw_file = nullptr;
        _raw_file_size = 0;
    }

    char*               _raw_file;
    std::ios::pos_type  _raw_file_size;
    struct SpriteFile   _data;
};

