#include <iostream>
#include <string>
#include <fstream>
#include <vector>
#include <sstream>
#include "Level.h"
using namespace std;

// Consts
const size_t MAGIC_SIZE = 5;
const char MAGICDEF[MAGIC_SIZE] = { 'L','E','V','L','3' };

// Vars
LevelHeaderv3 h;
SWORD alt[MAP_XZ_SIZE];
UBYTE noAccessFlags[MAP_XZ_SIZE];
struct PlayerSaveInfo pi[MAX_NUM_REAL_PLAYERS];
struct SunlightSaveInfo si;
vector<struct ThingSaveInfo> things;

// Functions
bool isLevelVersion3(std::ifstream& file);
void error(string errMsg);
bool loadLevel2(string filename);
bool saveLevel3(string filename);

int main(int argc, char* argv[]) {
	string file;

	if (argc > 1) {
		file = argv[1];
	}
	else {
		cout << "Please enter a file name (without extension): ";
		getline(cin, file);
	}

	if (!loadLevel2(file)) {
		error("Cannot open file!");
	}
	else {
		if (!saveLevel3(file)) {
			error("Cannot save file!");
		}
	}

	cout << "Completed Successfully!";
	return 0;
}

bool loadLevel2(string filename) {
	ostringstream ss;
	LevelHeader v2h;
	UBYTE dummy[MAP_XZ_SIZE*2];
	ThingSaveInfo t;

	// Load HDR
	ss << filename << ".hdr";
	ifstream HDR(ss.str(), ios::binary);

	if (HDR.is_open()) {
		HDR.read((char*)&v2h, sizeof(struct LevelHeader));
		HDR.close();
	}
	else {
		return false;
	}
	ss.str(""); // Clear stringstream

	// Convert Level2 to Level3
	memcpy(&h, &v2h, sizeof(struct LevelHeader));

	// Setup defaults
	h.MaxAltPoints = MAP_XZ_SIZE;
	h.MaxNumPlayers = MAX_NUM_REAL_PLAYERS;
	h.Version = LEVEL3_VERSION;
	h.MaxNumObjects = 0; // Not defined yet!

	ss << filename << ".dat";
	ifstream DAT(ss.str(), ios::binary);
	if (DAT.is_open()) {

		// Is file already version 3?
		if (isLevelVersion3(DAT)) {
			DAT.close();
			return false;
		}

		// Seek back top top because of MAGIC check.
		DAT.seekg(0, ios::beg);

		// Land height
		for (int i = 0; i < MAP_XZ_SIZE; i++) {
			if (!DAT.read((char*)&alt[i], sizeof(SWORD))) {
				DAT.close();
				return false;
			}
		}

		// Junk
		if (!DAT.read((char*)&dummy, ((MAP_XZ_SIZE * sizeof(UBYTE)) * 2))) { // Dont care, skip!
			DAT.close();
			return false;
		}

		// No Access Squares
		for (int i = 0; i < MAP_XZ_SIZE; i++) {
			if (!DAT.read((char*)&noAccessFlags[i], sizeof(UBYTE))) {
				DAT.close();
				return false;
			}
		}

		// PlayerInfo
		for (int i = 0; i < MAX_NUM_REAL_PLAYERS; i++) {
			if (!DAT.read((char*)&pi[i], sizeof(struct PlayerSaveInfo))) {
				DAT.close();
				return false;
			}
		}

		// Sunlight info
		if (!DAT.read((char*)&si, sizeof(struct SunlightSaveInfo))) {
			DAT.close();
			return false;
		}

		// Things!
		for (int i = 0; i < MAX_NUM_LEVEL_THINGS; i++) {
			if (!DAT.read((char*)&t, sizeof(struct ThingSaveInfo))) {
				DAT.close();
				return false;
			}

			if (t.Type != T_MODEL_NONE)
			{
				things.push_back(t);
			}
			else {
				break;
			}
		}

		// Set objects
		h.MaxNumObjects = things.size();

		// Make sure scripts is memset to 0.
		memset(&h.Script2, 0, sizeof(char[MAX_NUM_SCRIPT2][MAX_LENGTH_SAVE_NAMEv2]) );

		DAT.close();
	}
	else {
		return false;
	}
	return true;
}

bool saveLevel3(string filename) {
	ostringstream ss;
	ss << filename << ".dat";
	ofstream file(ss.str(), ios::trunc | ios::binary);

	if (file.is_open()) {
		file.write((char*)&MAGICDEF, MAGIC_SIZE);
		file.write((char*)&h, sizeof(struct LevelHeaderv3));
		file.write((char*)&alt, sizeof(SWORD) * h.MaxAltPoints);
		file.write((char*)&noAccessFlags, sizeof(UBYTE) * h.MaxAltPoints);
		file.write((char*)&pi, sizeof(struct PlayerSaveInfo) * h.MaxNumPlayers);
		file.write((char*)&si, sizeof(struct SunlightSaveInfo));

		for (int i = 0; i < things.size(); i++) {
			file.write((char*)&things[i], sizeof(struct ThingSaveInfo));
		}

		file.close();
	}
	else {
		return false;
	}
	return true;
}

bool isLevelVersion3(std::ifstream& file) {
	char MAGIC[MAGIC_SIZE];
	file.read((char*)&MAGIC, MAGIC_SIZE);

	for (int i = 0; i < MAGIC_SIZE; i++) {
		if (MAGIC[i] != MAGICDEF[i]) {
			return false; // MAGIC IS WRONG! 
		}
	}
	return true;
}

void error(string errMsg) {
	cerr << errMsg << "\n";
	exit(-1);
}

#pragma once
#include <Windows.h>

#define LEVEL3_VERSION						1
#define	MAP_SIZE_FACTOR 					2
#define MAP_X_SIZE							(256/MAP_SIZE_FACTOR)
#define MAP_Z_SIZE							(256/MAP_SIZE_FACTOR)
#define MAP_XZ_SIZE							(MAP_X_SIZE*MAP_Z_SIZE)
#define	MAX_NUM_TRIGGER_THINGS				10
#define	MAX_NUM_NORMAL_SPELLS				(32)
#define	MAX_LENGTH_SAVE_NAMEv2				(32)
#define	MAX_NUM_LEVELSv2					(30)
#define	MAX_NUM_SPECTATORS					1
#define	MAX_NUM_PLAYERS						(4+MAX_NUM_SPECTATORS)  //<RW> added one for hostbots
#define	MAX_NUM_REAL_PLAYERS				(MAX_NUM_PLAYERS-MAX_NUM_SPECTATORS)
#define	MAX_NUM_LEVEL_MARKERSv2				(256)
#define	MAX_NUM_LEVEL_THINGS				2000 // level files have 2000 things
#define	MAX_NUM_SCRIPT2						10

//=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
//	THINGS STUFF
//=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
#define		SPM_NORMAL				  			(0)
#define		SPM_INIT				  			(1)
#define		T_TYPE_NONE				  			(0)
#define		T_MODEL_NONE				   		(0)
#define		T_STATE_NONE						(0)

typedef int				SINT;
typedef signed long		SLONG;
typedef signed char		SBYTE;
typedef	unsigned char	UBYTE;
typedef signed short	SWORD;

struct		PlayerThings
{
	ULONG							SpellsAvailable;							// bit flagged info on spells available to player
	ULONG							BuildingsAvailable;							// bit flagged info on buildings available to player
	ULONG							BuildingsAvailableLevel;					// flagged if level temp available 
	ULONG							BuildingsAvailableOnce;						// flagged if one off available 
	union
	{
		ULONG							SpellsAvailableLevel;						// flagged if level temp available 
		ULONG							SpellsNotCharging;							// bit flagged as having been switched off by player
	};
	UBYTE							SpellsAvailableOnce[MAX_NUM_NORMAL_SPELLS];	// number of one shots available, per spell, indexed by spell model
	UWORD							VehiclesAvailable;							// bit flagged info on vehicles available to player
	UBYTE							TrainingManaOff;
	UBYTE							Flags;
};	

struct		LevelHeader
{
	struct PlayerThings				DefaultThings;							// default things for player 0 (if network game)... default things for other players will be taken from the computer players
	CHAR							Name[MAX_LENGTH_SAVE_NAMEv2];			// name of level
	UBYTE							NumPlayers;								// number of starting positions that have been defined
	UBYTE							ComputerPlayerIndex[MAX_NUM_PLAYERS - 2];	// computer player indices
	UBYTE							DefaultAllies[MAX_NUM_REAL_PLAYERS];			// starting allies on this level
	UBYTE							LevelType;								// defines colours on level
	UBYTE							ObjectsBankNum;							// defines objects bank used on level
	UBYTE							LevelFlags;								// wether to use fog, shaman omnipresence, etc.
	UBYTE							Pad[1];
	UWORD							Markers[MAX_NUM_LEVEL_MARKERSv2];		// marker points on level	
	UWORD							StartPos;								// start square to look at - can't use 0,0 ->this implies start at shaman
	UWORD							StartAngle;								// start angle for level
};	

struct		LevelHeaderv3
{
	struct PlayerThings				DefaultThings;							// default things for player 0 (if network game)... default things for other players will be taken from the computer players
	CHAR							Name[MAX_LENGTH_SAVE_NAMEv2];			// name of level
	UBYTE							NumPlayers;								// number of starting positions that have been defined
	UBYTE							ComputerPlayerIndex[MAX_NUM_PLAYERS - 2];	// computer player indices
	UBYTE							DefaultAllies[MAX_NUM_REAL_PLAYERS];			// starting allies on this level
	UBYTE							LevelType;								// defines colours on level
	UBYTE							ObjectsBankNum;							// defines objects bank used on level
	UBYTE							LevelFlags;								// wether to use fog, shaman omnipresence, etc.
	UBYTE							Pad[1];
	UWORD							Markers[MAX_NUM_LEVEL_MARKERSv2];		// marker points on level	
	UWORD							StartPos;								// start square to look at - can't use 0,0 ->this implies start at shaman
	UWORD							StartAngle;								// start angle for level
	UBYTE							Version;								// How many objects are in the level
	ULONG							MaxAltPoints;							// How many points are in the level
	ULONG							MaxNumObjects;							// How many objects are in the level
	ULONG							MaxNumPlayers;							// How many players are in the level
	CHAR							Script2[MAX_NUM_SCRIPT2][MAX_LENGTH_SAVE_NAMEv2];
};

struct MaxSaveInfo
{
	SLONG								Bluff[12];
};

struct TriggerSaveInfo
{
	UBYTE								TriggerType;
	UBYTE								CellRadius;
	UBYTE								RandomValue;
	SBYTE								NumOccurences;
	UWORD								TriggerCount;
	UWORD								EditorThingIdxs[MAX_NUM_TRIGGER_THINGS];
	SWORD								PrayTime;
	UBYTE								StartInactive;
	UBYTE								CreatePlayerOwned;
