{
	SLONG								Empty;
};

struct ShotSaveInfo
{
	SLONG								Empty;
};

struct EffectSaveInfo
{
	SLONG								Empty;
};

struct GeneralSaveInfo
{
	UBYTE								DiscoveryType;
	UBYTE								DiscoveryModel;
	UBYTE								AvailabilityType;
